import{_ as s,I as o,o as t,c as i,a6 as l,J as r}from"./chunks/framework.9im4mKfj.js";const k=JSON.parse('{"title":"MongoDB","description":"","frontmatter":{},"headers":[],"relativePath":"database/mongo.md","filePath":"database/mongo.md","lastUpdated":1791082088000}'),n={name:"database/mongo.md"};function d(c,a,p,h,m,g){const e=o("PDF");return t(),i("div",null,[a[0]||(a[0]=l('<h1 id="mongodb" tabindex="-1">MongoDB <a class="header-anchor" href="#mongodb" aria-label="Permalink to “MongoDB”">​</a></h1><p>MongoDB Atlas 雲端資料庫的設定與工具</p><h2 id="mongodb-atlas" tabindex="-1">MongoDB Atlas <a class="header-anchor" href="#mongodb-atlas" aria-label="Permalink to “MongoDB Atlas”">​</a></h2><p>課程使用 <a href="https://www.mongodb.com/atlas" target="_blank" rel="noreferrer">MongoDB Atlas</a> 免費雲端資料庫，不需要在電腦安裝 MongoDB<br> 在不同電腦上都能連到同一個資料庫</p><ol><li>註冊 MongoDB Atlas 帳號</li><li>建立 Cluster，方案選擇免費的 <code>Free</code>，地區選擇離台灣較近的地區</li><li>在 Database Access 建立資料庫使用者，設定帳號密碼</li><li>在 Network Access 加入 <code>0.0.0.0/0</code>，允許所有 IP 連線</li><li>在 Cluster 點選 Connect，選擇 Drivers，複製連線字串</li></ol><div class="danger custom-block"><p class="custom-block-title">注意</p><ul><li>開放所有 IP 後，任何人只要有帳號密碼就能連線，連線字串不能上傳到 GitHub</li><li>密碼建議只使用英文和數字，特殊符號會讓連線字串解析錯誤</li></ul></div><p>複製的連線字串沒有資料庫名稱，需要自己加在 <code>.net/</code> 和 <code>?</code> 之間<br> 沒有加的話，資料會存到預設的 <code>test</code> 資料庫</p><div class="language-ini line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DB_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=mongodb+srv://帳號:密碼@cluster0.xxxxx.mongodb.net/資料庫名稱?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">retryWrites</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true&amp;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">w</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=majority</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>如果想在自己的電腦安裝 MongoDB，可以參考<a href="https://www.mongodb.com/docs/manual/installation/" target="_blank" rel="noreferrer">官方安裝說明</a></p></div><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to “工具”">​</a></h2><p>可以使用下列工具檢視、編輯資料庫內容，Atlas 網站上的 Data Explorer 也有相同的功能</p><ul><li><a href="https://www.mongodb.com/products/compass" target="_blank" rel="noreferrer">MongoDB Compass</a></li><li><a href="https://marketplace.visualstudio.com/items?itemName=mongodb.mongodb-vscode" target="_blank" rel="noreferrer">MongoDB for VS Code</a></li></ul><h2 id="資料管理" tabindex="-1">資料管理 <a class="header-anchor" href="#資料管理" aria-label="Permalink to “資料管理”">​</a></h2><p>使用 Compass 可以匯入、匯出資料，支援 JSON 和 CSV 格式</p><ul><li>匯出：進入資料表後，點選 Export Data</li><li>匯入：進入資料表後，點選 Add Data，選擇 Import JSON or CSV file</li></ul><h2 id="資料庫規劃" tabindex="-1">資料庫規劃 <a class="header-anchor" href="#資料庫規劃" aria-label="Permalink to “資料庫規劃”">​</a></h2>',16)),r(e,{src:"/F2E-book/assets/ch26/uml.pdf"})])}const u=s(n,[["render",d]]);export{k as __pageData,u as default};
